<script setup lang="ts">
import {useHost} from '@minhanos/app-sdk'
import { Check, Layers3, Leaf, Monitor } from 'lucide-vue-next'
import { api } from '../api'
import { useDesktop } from '../store'
// Desktop's own Settings panel (com.minhanos.desktop/appearance). Values persist via profile and preferences APIs.
defineProps<{ active?: boolean }>()
const host = useHost()
const desktop = useDesktop()
const t = (key: string) => { host.profile.value.locale; return host.i18n.t(key) }
function setTheme(theme: 'light' | 'dark') { void host.updateProfile(api,{theme}).catch(e=>desktop.toast(host.errorMessage(e))); desktop.preferences.theme = theme; desktop.saveSoon() }
function setWallpaper(wallpaper: 'mountain' | 'midnight' | 'sage') { desktop.preferences.wallpaper = wallpaper; desktop.saveSoon() }
</script>

<template>
  <main class="standard-content"><div class="page-eyebrow">{{ t('desktop.appearance.eyebrow') }}</div><h1>{{ t('desktop.appearance.title') }}</h1><p class="muted">{{ t('desktop.appearance.hint') }}</p><section class="workspace-mode-setting"><h3>{{ t('desktop.appearance.mode') }}</h3><p class="muted small-text">{{ t('desktop.appearance.modeHint') }}</p><div class="workspace-mode-options"><button :aria-label="t('desktop.appearance.focusLabel')" :aria-pressed="desktop.preferences.mode === 'focus'" :class="{chosen:desktop.preferences.mode === 'focus'}" @click="desktop.setMode('focus')"><Monitor :size="24"/><strong>{{ t('desktop.appearance.focus') }}</strong><small>{{ t('desktop.appearance.focusHint') }}</small><Check v-if="desktop.preferences.mode === 'focus'" :size="16"/></button><button :aria-label="t('desktop.appearance.windowsLabel')" :aria-pressed="desktop.preferences.mode === 'windows'" :class="{chosen:desktop.preferences.mode === 'windows'}" @click="desktop.setMode('windows')"><Layers3 :size="24"/><strong>{{ t('desktop.appearance.windows') }}</strong><small>{{ t('desktop.appearance.windowsHint') }}</small><Check v-if="desktop.preferences.mode === 'windows'" :size="16"/></button></div></section><h3 class="settings-section">{{ t('desktop.appearance.display') }}</h3><div class="theme-options"><button v-for="theme in (['light','dark'] as const)" :key="theme" class="theme-option" :class="{ chosen: desktop.preferences.theme === theme }" :aria-pressed="desktop.preferences.theme === theme" @click="setTheme(theme)"><div :class="['theme-preview',theme]"><span></span><i></i><b></b></div><span>{{ t('desktop.appearance.' + theme) }}<Check v-if="desktop.preferences.theme === theme" :size="16" /></span></button></div><h3 class="settings-section">{{ t('desktop.appearance.wallpaper') }}</h3><div class="wallpaper-options"><button v-for="wallpaper in (['mountain','midnight','sage'] as const)" :key="wallpaper" class="wallpaper-option" :class="{ chosen: desktop.preferences.wallpaper === wallpaper }" :aria-pressed="desktop.preferences.wallpaper === wallpaper" @click="setWallpaper(wallpaper)"><span :class="['wallpaper-preview',wallpaper]"><Check v-if="desktop.preferences.wallpaper === wallpaper" :size="22" /></span><span>{{ t('desktop.appearance.' + wallpaper) }}</span></button></div><div class="info-panel"><Leaf :size="19" /><div><strong>{{ t('desktop.appearance.infoTitle') }}</strong><p>{{ t('desktop.appearance.infoText') }}</p></div></div><p v-if="desktop.saveError" class="inline-error">{{ t('desktop.save.failed') }} <button class="text-button" @click="desktop.persist">{{ t('desktop.appearance.retry') }}</button></p></main>
</template>
